    faceBlend(context, id + "blend1", { "side1" : qOwnedByBody(qBodyType(qCreatedBy(id + "floor", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide1" : true, "side2" : qOwnedByBody(qBodyType(qCreatedBy(id + "wall", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide2" : false, "propagation" : false, "crossSection" : FaceBlendCrossSection.ROLLING_BALL, "blendControlType" : BlendControlType.RADIUS, "radius" : 5 * millimeter, "asymmetric" : false, "crossSectionShape" : FaceBlendCrossSectionShape.CIRCULAR, "tangentHoldLines" : false, "conicHoldLines" : false, "hasCliffEdges" : false, "hasCaps" : false, "hasLimits" : false, "hasHelpPoint" : false, "trim" : FaceBlendTrimType.NO_TRIM, "detach" : false, "showSelection" : false, "showIsocurves" : false });
