// loft: a circle to an equal circle, guided by an arc bulging out between them
export function c027(context is Context, id is Id)
{
    const g = newSketchOnPlane(context, id + "g", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(g, "arc1", { "start" : vector(10, 0) * millimeter, "mid" : vector(13, 15) * millimeter, "end" : vector(10, 30) * millimeter });
    skSolve(g);
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s1, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 30) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s2, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(s2);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }], "guidesArray" : [{ "guideEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "g", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }] });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)) };
}
